  1  /**
  2   * Acceptance tests for AC-1 (User registration and authentication)
  3   * and AC-8 (Users can register, login, logout securely).
  4   *
  5   * These tests verify:
  6   * - AC-1: A new user can register, then log in and receive a JWT access token
  7   * - AC-8: After logout, the same token cannot access protected endpoints (401)
  8   *
  9   * Each test creates uniquely-named records (via uniqueSuffix) so tests
 10   * don't interfere with each other on the shared service instance.
 11   */
 12  
 13  import { test, expect } from '@playwright/test';
 14  import { uniqueSuffix, registerUser, loginUser } from './helpers.js';
 15  
 16  /**
 17   * [AC-1] User can register with unique credentials and receive 201
 18   *
 19   * Verifies that POST /api/register with valid data returns 201 Created
 20   * and the response body contains the expected user fields (id, username, email, created_at).
 21   * The test creates a user with a unique suffix to avoid conflicts with other tests.
 22   */
 23  test('[AC-1] registration creates a new user', async ({ request }) => {
 24    const suffix = uniqueSuffix();
 25    const response = await registerUser(request, suffix);
 26  
 27    expect(response.status()).toBe(201);
 28    const body = await response.json();
 29  
 30    expect(body).toHaveProperty('id');
 31    expect(typeof body.id).toBe('number');
 32    expect(body).toHaveProperty('username', `testuser_${suffix}`);
 33    expect(body).toHaveProperty('email', `${suffix}@example.com`);
 34    expect(body).toHaveProperty('created_at');
 35    expect(typeof body.created_at).toBe('string');
 36  });
 37  
 38  /**
 39   * [AC-1] Registration rejects duplicate username
 40   *
 41   * Verifies that registering with an already-used username returns 409 Conflict
 42   * with the expected error message.
 43   */
 44  test('[AC-1] registration rejects duplicate username', async ({ request }) => {
 45    const suffix = uniqueSuffix();
 46    const username = `dupuser_${suffix}`;
 47    const email = `first_${suffix}@example.com`;
 48  
 49    // First registration should succeed
 50    const firstResponse = await request.post('/api/register', {
 51      data: { username, email, password: 'SecurePass123!' },
 52    });
 53    expect(firstResponse.status()).toBe(201);
 54  
 55    // Second registration with same username should fail
 56    const secondResponse = await request.post('/api/register', {
 57      data: { username, email: `second_${suffix}@example.com`, password: 'SecurePass123!' },
 58    });
 59    expect(secondResponse.status()).toBe(409);
 60    const body = await secondResponse.json();
 61    expect(body.error).toBe('Username or email already exists');
 62  });
 63  
 64  /**
 65   * [AC-1] Registration rejects duplicate email
 66   *
 67   * Verifies that registering with an already-used email returns 409 Conflict.
 68   */
 69  test('[AC-1] registration rejects duplicate email', async ({ request }) => {
 70    const suffix = uniqueSuffix();
 71    const email = `dupe_${suffix}@example.com`;
 72    const username = `first_${suffix}`;
 73  
 74    // First registration should succeed
 75    const firstResponse = await request.post('/api/register', {
 76      data: { username, email, password: 'SecurePass123!' },
 77    });
 78    expect(firstResponse.status()).toBe(201);
 79  
 80    // Second registration with same email should fail
 81    const secondResponse = await request.post('/api/register', {
 82      data: { username: `second_${suffix}`, email, password: 'SecurePass123!' },
 83    });
 84    expect(secondResponse.status()).toBe(409);
 85    const body = await secondResponse.json();
 86    expect(body.error).toBe('Username or email already exists');
 87  });
