 89  /**
 90   * [AC-1] Login with valid credentials returns JWT access token
 91   *
 92   * Registers a user, then logs in with those credentials.
 93   * Asserts the response contains access_token (a JWT string) and token_type 'bearer'.
 94   */
 95  test('[AC-1] login with valid credentials returns JWT token', async ({ request }) => {
 96    const suffix = uniqueSuffix();
 97    const email = `${suffix}@example.com`;
 98    const password = 'SecurePass123!';
 99  
100    // Register first
101    const registerResponse = await registerUser(request, suffix);
102    expect(registerResponse.status()).toBe(201);
103  
104    // Now login
105    const loginResponse = await request.post('/api/login', {
106      data: { email, password },
107    });
108    expect(loginResponse.status()).toBe(200);
109    const body = await loginResponse.json();
110  
111    expect(body).toHaveProperty('access_token');
112    expect(typeof body.access_token).toBe('string');
113    expect(body.access_token.length).toBeGreaterThan(0);
114    // JWT tokens have three dot-separated parts
115    expect(body.access_token.split('.').length).toBe(3);
116    expect(body).toHaveProperty('token_type', 'bearer');
117  
118    // Login also sets a refresh_token cookie (AC-1)
119    const setCookie = loginResponse.headers()['set-cookie'];
120    expect(typeof setCookie).toBe('string');
121    expect(setCookie).toContain('refresh_token=');
122  });
123  
124  /**
125   * [AC-1] Login with invalid credentials returns 401
126   *
127   * Verifies that logging in with wrong password returns 401 Unauthorized.
128   */
129  test('[AC-1] login with invalid credentials returns 401', async ({ request }) => {
130    const suffix = uniqueSuffix();
131    const email = `${suffix}@example.com`;
132  
133    // Register a user
134    await registerUser(request, suffix);
135  
136    // Login with wrong password
137    const loginResponse = await request.post('/api/login', {
138      data: { email, password: 'WrongPassword123!' },
139    });
140    expect(loginResponse.status()).toBe(401);
141    const body = await loginResponse.json();
142    expect(body.error).toBe('Invalid credentials');
143  });
