145  /**
146   * [AC-8] After logout, token cannot access protected endpoints
147   *
148   * Registers a user, logs in to get a token, calls logout, then attempts
149   * to access /api/health (a protected endpoint) with the same token.
150   * Asserts the response is 401 Unauthorized.
151   */
152  test('[AC-8] logout invalidates the access token', async ({ request }) => {
153    const suffix = uniqueSuffix();
154    const email = `${suffix}@example.com`;
155    const password = 'SecurePass123!';
156  
157    // Register and login
158    const registerResponse = await registerUser(request, suffix);
159    expect(registerResponse.status()).toBe(201);
160  
161    const loginResponse = await request.post('/api/login', {
162      data: { email, password },
163    });
164    expect(loginResponse.status()).toBe(200);
165    const loginBody = await loginResponse.json();
166    const token = loginBody.access_token;
167  
168    // Logout
169    const logoutResponse = await request.post('/api/logout', {
170      headers: { Authorization: `Bearer ${token}` },
171    });
172    expect(logoutResponse.status()).toBe(200);
173    const logoutBody = await logoutResponse.json();
174    expect(logoutBody.message).toBe('Logged out successfully');
175  
176    // Now try to access a protected endpoint with the same token
177    const protectedResponse = await request.get('/api/tasks', {
178      headers: { Authorization: `Bearer ${token}` },
179    });
180    expect(protectedResponse.status()).toBe(401);
181    const protectedBody = await protectedResponse.json();
182    expect(protectedBody).toHaveProperty('error');
183  });

  1  /**
  2   * Acceptance tests for AC-13 (All endpoints have proper error handling).
  3   *
  4   * Verifies that:
  5   * - POST /register with empty body returns 422
  6   * - POST /login with missing fields returns 401
  7   * - POST /tasks without authorization returns 401
  8   * - PUT /tasks/{id} with invalid JSON returns 422
  9   *
 10   * Each test checks the HTTP status code and that the response body contains
 11   * an 'error' field (and 'correlation_id' where specified).
 12   */
 13  
 14  import { test, expect } from '@playwright/test';
 15  
 16  /**
 17   * [AC-13] POST /register with empty body returns 422
 18   *
 19   * Verifies that sending an empty body to the registration endpoint
 20   * returns a 422 Validation Error with the expected error structure.
 21   */
 22  test('[AC-13] POST /register with empty body returns 422', async ({ request }) => {
 23    const response = await request.post('/api/register', {
 24      data: {},
 25    });
 26  
 27    expect(response.status()).toBe(422);
 28    const body = await response.json();
 29  
 30    expect(body).toHaveProperty('error');
 31    expect(body.error).toBe('Validation error');
 32    expect(body).toHaveProperty('correlation_id');
 33    expect(typeof body.correlation_id).toBe('string');
 34    expect(body).toHaveProperty('details');
 35    expect(Array.isArray(body.details)).toBeTruthy();
 36  });
 37  
 38  /**
 39   * [AC-13] POST /login with missing fields returns 401
 40   *
 41   * Verifies that logging in with missing email or password returns 401.
 42   */
 43  test('[AC-13] POST /login with missing email returns 401', async ({ request }) => {
 44    const response = await request.post('/api/login', {
 45      data: { password: 'SomePassword123!' },
 46    });
 47  
 48    expect(response.status()).toBe(401);
 49    const body = await response.json();
 50    expect(body).toHaveProperty('error');
 51  });
 52  
 53  /**
 54   * [AC-13] POST /login with missing password returns 401
 55   *
 56   * Verifies that logging in with missing password returns 401.
 57   */
 58  test('[AC-13] POST /login with missing password returns 401', async ({ request }) => {
 59    const response = await request.post('/api/login', {
 60      data: { email: 'test@example.com' },
 61    });
 62  
 63    expect(response.status()).toBe(401);
 64    const body = await response.json();
 65    expect(body).toHaveProperty('error');
 66  });
 67  
 68  /**
 69   * [AC-13] POST /tasks without authorization returns 401
 70   *
 71   * Verifies that creating a task without an Authorization header
 72   * returns 401 Unauthorized.
 73   */
 74  test('[AC-13] POST /tasks without authorization returns 401', async ({ request }) => {
 75    const response = await request.post('/api/tasks', {
 76      data: { title: 'Unauthorized Task', priority: 'high' },
 77    });
 78  
 79    expect(response.status()).toBe(401);
 80    const body = await response.json();
 81    expect(body).toHaveProperty('error');
 82    expect(body).toHaveProperty('correlation_id');
 83  });
 84  
 85  /**
 86   * [AC-13] PUT /tasks/{id} with invalid JSON returns 422
 87   *
 88   * Verifies that sending malformed JSON to the task update endpoint
 89   * returns 422 Validation Error.
 90   */
 91  test('[AC-13] PUT /tasks/1 with invalid JSON returns 422', async ({ request }) => {
 92    const response = await request.put('/api/tasks/1', {
 93      headers: {
 94        'Content-Type': 'application/json',
 95      },
 96      // Send invalid JSON
 97      data: '{invalid json}',
 98    });
 99  
100    expect(response.status()).toBe(422);
101    const body = await response.json();
102    expect(body).toHaveProperty('error');
103  });
104  
105  /**
106   * [AC-13] GET /tasks without authorization returns 401
107   *
108   * Verifies that accessing the task list without authentication returns 401.
109   */
110  test('[AC-13] GET /tasks without authorization returns 401', async ({ request }) => {
111    const response = await request.get('/api/tasks');
112  
113    expect(response.status()).toBe(401);
114    const body = await response.json();
115    expect(body).toHaveProperty('error');
116  });
