118  /**
119   * [AC-13] GET /tasks/{id} with non-existent ID returns 404
120   *
121   * Verifies that requesting a task that doesn't exist returns 404.
122   */
123  test('[AC-13] GET /tasks/999999 with invalid token returns 401', async ({ request }) => {
124      const response = await request.get('/api/tasks/999999', {
125        headers: { Authorization: 'Bearer fake-token' },
126      });
127  
128      expect(response.status()).toBe(401);
129      const body = await response.json();
130      expect(body).toHaveProperty('error');
131    });

  1  /**
  2   * Shared helpers for acceptance tests.
  3   *
  4   * These utilities are imported by every test file so later sprints can
  5   * reuse the same registration / login / task-creation primitives without
  6   * duplicating code.  Each helper is deliberately stateless except for the
  7   * data it creates under a unique namespace (the `suffix` parameter), so
  8   * tests never interfere with one another even though they share the same
  9   * service instance.
 10   *
 11   * All tests must create their own data under unique names and never assume
 12   * the service starts empty — other tests' records may be present.
 13   */
 14  
 15  import { expect } from '@playwright/test';
 16  
 17  /**
 18   * Generate a random suffix so every test creates uniquely-named records.
 19   * @returns {string} A short random string.
 20   */
 21  export function uniqueSuffix() {
 22    // 6 random hex chars → ~16M combinations, enough for test isolation.
 23    return Math.random().toString(16).slice(2, 8);
 24  }
 25  
 26  /**
 27   * Register a new user and return the parsed response body.
 28   *
 29   * @param {import('@playwright/test').APIRequestContext} request — Playwright request fixture.
 30   * @param {string} suffix — Unique suffix for this test's identity.
 31   * @returns {Promise<object>} Parsed JSON body of the registration response.
 32   */
 33  export async function registerUser(request, suffix) {
 34    const username = `testuser_${suffix}`;
 35    const email = `${suffix}@example.com`;
 36    const password = 'SecurePass123!';
 37    const response = await request.post('/api/register', {
 38      data: { username, email, password },
 39    });
 40    return response;
 41  }
 42  
 43  /**
 44   * Log in a user and return the parsed JSON body containing the access token.
 45   *
 46   * @param {import('@playwright/test').APIRequestContext} request
 47   * @param {string} email — User's email address.
 48   * @param {string} password — User's password.
 49   * @returns {Promise<object>} Parsed JSON body: `{ access_token, token_type }`.
 50   */
 51  export async function loginUser(request, email, password) {
 52    const response = await request.post('/api/login', {
 53      data: { email, password },
 54    });
 55    return response;
 56  }
 57  
 58  /**
 59   * Create a task via the API and return the parsed response body.
 60   *
 61   * @param {import('@playwright/test').APIRequestContext} request
 62   * @param {string} token — Bearer token string.
 63   * @param {object} options
 64   * @param {string} [options.title] — Task title (default "Test Task <suffix>").
 65   * @param {string} [options.suffix] — Unique suffix appended to title.
 66   * @param {string} [options.priority] — Priority value.
 67   * @returns {Promise<object>} Parsed JSON body of the created task.
 68   */
 69  export async function createTask(request, token, { title, suffix, priority } = {}) {
 70    const taskTitle = title || `Test Task${suffix ? ' ' + suffix : ''}`;
 71    const response = await request.post('/api/tasks', {
 72      headers: { Authorization: `Bearer ${token}` },
 73      data: {
 74        title: taskTitle,
 75        priority: priority || 'medium',
 76        status: 'pending',
 77      },
 78    });
 79    return response;
 80  }
 81  
 82  /**
 83   * Get a single task by ID and return the parsed JSON body.
 84   *
 85   * @param {import('@playwright/test').APIRequestContext} request
 86   * @param {string} token — Bearer token string.
 87   * @param {number} taskId — The task's numeric ID.
 88   * @returns {Promise<object>} Parsed JSON body of the task.
 89   */
 90  export async function getTask(request, token, taskId) {
 91    const response = await request.get(`/api/tasks/${taskId}`, {
 92      headers: { Authorization: `Bearer ${token}` },
 93    });
 94    return response;
 95  }
 96  
 97  /**
 98   * Update a task via PUT and return the parsed JSON body.
 99   *
100   * @param {import('@playwright/test').APIRequestContext} request
101   * @param {string} token — Bearer token string.
102   * @param {number} taskId — The task's numeric ID.
103   * @param {object} updates — Fields to update.
104   * @returns {Promise<object>} Parsed JSON body of the updated task.
105   */
106  export async function updateTask(request, token, taskId, updates) {
107    const response = await request.put(`/api/tasks/${taskId}`, {
108      headers: { Authorization: `Bearer ${token}` },
109      data: updates,
110    });
111    return response;
112  }
113  
114  /**
115   * Delete a task and return the parsed JSON body.
116   *
117   * @param {import('@playwright/test').APIRequestContext} request
118   * @param {string} token — Bearer token string.
119   * @param {number} taskId — The task's numeric ID.
120   * @returns {Promise<object>} Parsed JSON body.
121   */
122  export async function deleteTask(request, token, taskId) {
123    const response = await request.delete(`/api/tasks/${taskId}`, {
124      headers: { Authorization: `Bearer ${token}` },
125    });
126    return response;
127  }
128  
129  /**
130   * Complete a full registration + login cycle, returning both the response
131   * objects and the access token string.
132   *
133   * @param {import('@playwright/test').APIRequestContext} request
134   * @param {string} suffix — Unique suffix for this test's identity.
135   * @returns {Promise<{registerResponse: object, loginResponse: object, token: string, email: string, password: string, username: string}>}
136   */
137  export async function registerAndLogin(request, suffix) {
138    const username = `testuser_${suffix}`;
139    const email = `${suffix}@example.com`;
140    const password = 'SecurePass123!';
141  
142      const registerResponse = await registerUser(request, suffix);
143      expect(registerResponse.status()).toBe(201);
144  
145      const loginResponse = await loginUser(request, email, password);
146      expect(loginResponse.status()).toBe(200);
147  
148    const loginBody = await loginResponse.json();
149    return {
150      registerResponse,
151      loginResponse,
152      token: loginBody.access_token,
153      email,
154      password,
155      username,
156    };
157  }
